/* Barcode QR viewer */
.qr-holder{max-width:320px;margin:18px auto 15px;background:#fff;padding:17px;border:1px solid #dde9f8;border-radius:18px;box-shadow:0 8px 30px #1959a318}
#qrCanvas{display:block;width:100%;height:auto;aspect-ratio:1/1;image-rendering:pixelated}
.qr-tips{text-align:center;font-size:13px;color:#607a9b;line-height:1.65}
.scan-stage{position:relative;max-width:440px;margin:16px auto 0;aspect-ratio:1 / 1;border-radius:18px;overflow:hidden;background:#152c46;border:1px solid #dbe7f9}
#scanVideo{width:100%;height:100%;display:block;object-fit:cover}
.scan-frame{position:absolute;inset:19%;border:3px solid #8cddff;border-radius:17px;box-shadow:0 0 0 120px #07172b2a;pointer-events:none}
.scan-frame:before,.scan-frame:after{position:absolute;content:'';width:33px;height:33px;border-color:#42e8a9;border-style:solid}
.scan-frame:before{top:-3px;left:-3px;border-width:5px 0 0 5px;border-top-left-radius:13px}
.scan-frame:after{right:-3px;bottom:-3px;border-width:0 5px 5px 0;border-bottom-right-radius:13px}
.scanning-line{position:absolute;left:21%;width:58%;height:2px;background:#48d2fe;box-shadow:0 0 13px #1be4ff;animation:scanmove 2.4s ease-in-out infinite alternate;pointer-events:none}
@keyframes scanmove{from{top:24%}to{top:76%}}
.status-center{text-align:center;margin:15px auto 0;font-size:13px;color:#557392;line-height:1.5}
.action-group{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin-top:15px}
.mini-warning{color:#536a87;font-size:12px;line-height:1.65;margin-top:14px;text-align:center}
#remoteFiles{margin-top:22px}
#scannerPane{margin-top:9px}


