@media(max-width:700px){.football-nav{padding:11px 16px;min-height:66px}.brand-lines strong{font-size:15px}.brand-lines small{font-size:7px;letter-spacing:1.1px}.logo-mark{width:38px;height:38px;font-size:21px}.nav-links{gap:2px}.navlink{padding:9px 6px;font-size:11px}.nav-transfer{margin-left:5px;padding:10px 9px}.stadium-hero{min-height:auto}.hero-container{grid-template-columns:1fr;padding:42px 18px 34px;gap:38px}.hero-copy h1{font-size:clamp(41px,9vw,63px);letter-spacing:-2.2px;margin:19px 0}.hero-copy p{font-size:14px}.hero-kicker{font-size:9px}.hero-stats{margin-top:29px;gap:17px}.hero-stats strong{font-size:22px}.hero-stats small{font-size:8px}.pitch-scene{max-width:420px;width:100%;justify-self:center}.pitch-grid{min-height:230px;aspect-ratio:1.35}.stadium-bottom{padding:14px 18px}.home-content{padding:44px 17px 50px}.section-top{display:block}.section-top p{margin-top:14px}.feature-grid{grid-template-columns:1fr;gap:12px}.feature-card{min-height:225px;padding:23px}.feature-num{margin-top:13px}.feature-bottom{padding-top:19px}.strategy-banner{display:block;padding:23px}.strategy-banner div:nth-child(2){margin:10px 0 22px}.strategy-banner button{width:100%}.football-footer{padding:22px 17px;flex-wrap:wrap}.transfer-headline{align-items:flex-start;flex-direction:column;gap:14px}.idle-chip{align-self:flex-start}.transfer-wrap{padding:19px 14px 45px}.transfer-wrap .content{padding:21px 15px}.transfer-headline p{font-size:13px}}
@media(max-width:410px){.navlink:not(.nav-transfer){display:none}.nav-transfer{font-size:11px}.hero-primary,.hero-secondary{width:100%}.pitch-grid{min-height:220px}.player{width:23px;height:23px;font-size:9px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.pitch-scene{transition:none}}
/* Football ball is the only direct entry point to the QR transfer page. */
.brand-cluster{gap:10px}.brand-wordmark{border:0;background:transparent;color:inherit;text-align:left;padding:0;cursor:pointer}.football-ball-link{color:inherit;cursor:pointer;outline-offset:3px;transition:transform .18s,background .18s,border-color .18s}.football-ball-link:hover,.football-ball-link:focus-visible{background:#b5f44845;border-color:#b5f448;transform:scale(1.09)}.football-ball-link:active{transform:scale(.96)}
