.source-display{display:flex;align-items:center;gap:10px;justify-content:space-between;flex-wrap:wrap;margin:13px 0;color:#56756c;font-size:12px;word-break:break-all}
.source-display b{color:#143f30;font-weight:850}
.receiver-paste{display:flex;gap:9px;margin-top:15px}
.receiver-paste input{flex:1;min-width:0}
.receiver-paste button{flex-shrink:0}
